#include <stdio.h>

int main() {
    int values[] = {8, 12, 32, 33};
    for (int i = 0; i < 4; i++) {
        int n = values[i];
        int ok = n > 0 && (n & (n - 1)) == 0;
        printf("%d: %d\n", values[i], ok);
    }
    return 0;
}
